const loginForm=document.querySelector("#loginForm"),loginStatus=document.querySelector("#loginStatus"),ADMIN_LAST_VIEW_STORAGE_KEY="mawg.admin.lastView";function getAdminDestination(){const t=new URLSearchParams(window.location.search).get("next");if(t&&/^\/admin(?:\.html)?(?:#[-a-z]+)?$/i.test(t))return t;try{const t=window.sessionStorage.getItem("mawg.admin.lastView");if(t&&/^[a-z]+$/.test(t))return`/admin.html#${t}`}catch{}return"/admin.html#dashboard"}function setLoginStatus(t,n=!1){loginStatus&&(loginStatus.textContent=t,loginStatus.classList.toggle("is-error",n))}async function checkSession(){const t=await fetch("/api/admin/session",{credentials:"same-origin"});(await t.json()).authenticated&&(window.location.href=getAdminDestination())}loginForm?.addEventListener("submit",async t=>{t.preventDefault(),setLoginStatus("Validando acceso...");const n=Object.fromEntries(new FormData(loginForm).entries());try{const t=await fetch("/api/admin/login",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)}),e=await t.json().catch(()=>({}));if(!t.ok)throw new Error(e.error||"No se pudo iniciar sesion.");window.location.href=getAdminDestination()}catch(t){setLoginStatus(t.message,!0)}}),checkSession().catch(()=>{setLoginStatus("")});
